'use strict';
// Safe, self-contained .env reader — no network, no third-party dependency.
const fs = require('fs');

function load(path) {
  const raw = fs.readFileSync(path || '.env.test', 'utf8');
  const cfg = {};
  for (const line of raw.split('\n')) {
    const trimmed = line.trim();
    if (!trimmed || trimmed.startsWith('#')) continue;
    const i = line.indexOf('=');
    if (i > 0) cfg[line.slice(0, i).trim()] = line.slice(i + 1).trim();
  }
  return cfg;
}

const config = load('.env.test');
console.log('Config key names:');
for (const key of Object.keys(config)) console.log('  - ' + key);

